import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.Czhw_PXq.js";const b=JSON.parse('{"title":"ADR 004: Observability & Resilience Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/004-observability.md","filePath":"adr/004-observability.md"}'),o={name:"adr/004-observability.md"};function n(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-004-observability-resilience-strategy" tabindex="-1">ADR 004: Observability &amp; Resilience Strategy <a class="header-anchor" href="#adr-004-observability-resilience-strategy" aria-label="Permalink to &quot;ADR 004: Observability &amp; Resilience Strategy&quot;">​</a></h1><ul><li>Status: accepted</li><li>Deciders: Elena, Senior Observability Engineer</li><li>Date: 2026-03-04</li></ul><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>In production, silent failures (e.g., PDF parsing errors, AI timeouts) destroy user trust. We need a way to track, diagnose, and resolve errors without relying on user reports.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><strong>Visibility</strong>: We need to see what happened <em>before</em> the crash.</li><li><strong>Full Stack</strong>: Errors often span across Frontend (Network Error) and Backend (500).</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Console Logs</strong>: Basic, standard output.</li><li><strong>ELK Stack</strong>: Elastic Search, Logstash, Kibana (Self-hosted).</li><li><strong>Sentry</strong>: SaaS Error Tracking.</li></ul><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>&quot;Sentry&quot;</strong>.</p><h3 id="justification" tabindex="-1">Justification <a class="header-anchor" href="#justification" aria-label="Permalink to &quot;Justification&quot;">​</a></h3><ul><li><strong>Zero-Config</strong>: <code>@sentry/node</code> and <code>@sentry/react</code> auto-instrument express and react components.</li><li><strong>Context</strong>: Sentry captures the &quot;Breadcrumbs&quot; (actions leading to error), which is critical for debugging AI hallucinations or state issues.</li><li><strong>Performance</strong>: Free tier includes basic performance monitoring (transactions).</li></ul><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li>Real-time alerting.</li><li>Stack traces are preserved (with source maps).</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li>Dependency on external SaaS.</li></ul>',16)])])}const g=t(o,[["render",n]]);export{b as __pageData,g as default};
